export type BlogArticle = { slug: string; title: string; category: string; excerpt: string; tags: string[]; publishedAt: string; updatedAt: string; featured?: boolean; image: string; imageAlt: string; service?: { label: string; href: string }; sections: BlogSection[]; sources?: { label: string; href: string }[] };

