function contentFor(index:number,title:string):BlogSection[] {
 const base:BlogSection[] = [
  {heading:"Start with the decision in front of you",paragraphs:[`The useful way to approach â€œ${title}â€ is to turn a broad music-business question into a sequence of decisions you can check. Start by writing down the outcome you need, the people who control relevant rights, the files or information required, and the deadline that actually matters. This prevents an avoidable rush from becoming a release problem.`,`Independent artists often work across songwriting, recording, production and promotion at once. Keep a simple source-of-truth document for the project: the final title, version, contributors, rights contacts, delivery status and next action. Update it whenever an agreement or asset changes.`]},
  {heading:"Build a reliable workflow",paragraphs:[`First, gather the materials before committing to a date. That may mean a final approved master, artwork, complete credits, signed permissions, a licence or a written split agreement. A draft is useful for review, but mark it clearly so no one mistakes it for the release version.`,`Second, assign responsibility. One person should own the final check even when several collaborators supply information. Ask each contributor to verify the spelling of their name, their role and the agreed credit. Preserve dated approvals and the final files in a backed-up folder.`],bullets:["Keep one approved final version and archive superseded drafts.","Use clear filenames with title, version and date; avoid ambiguous labels such as final-final.","Record rights, licences and contributor approvals in writing.","Leave time for corrections and partner review before a public date."]},
  {heading:"Common choices and trade-offs",paragraphs:[`There is rarely one choice that suits every artist. Compare the options by what you receive, what you pay, what rights you grant, who is responsible for follow-up and what happens if your plans change. Read the actual terms that apply to your release; a headline or social post is not a substitute for a contract.`,`For Indian artists working with collaborators in different cities or countries, write down the territory, term, permitted uses, credit format and payment process. If a term is unclear or the decision could materially affect your rights, get advice from a qualified professional familiar with the relevant jurisdiction.`],table:{headers:["Check","Ask before you proceed"],rows:[["Rights","Who owns or controls each underlying work and recording?"],["Scope","Which uses, stores, territories and versions are covered?"],["Money","What fees, deductions, shares or reporting conditions apply?"],["Timing","What review, delivery or payment steps can affect the schedule?"],["Evidence","Where are the signed terms, approvals and final files stored?"]] }},
  {heading:"A practical checklist",paragraphs:[`Before taking the next step, confirm the following items with the people involved. If something is not settled, make the unresolved point visible and decide who will resolve it and by when. A short written record is more useful than relying on a memory of a conversation.`],bullets:["Confirm the final material and version being discussed.","Check contributor names, roles and written agreements.","Verify that samples, beats, artwork and other third-party material are cleared for the intended use.","Review the relevant current platform, distributor or service terms.","Save receipts, approvals, identifiers and correspondence with the project files.","Set a realistic date with contingency for review and corrections."]},
  {heading:"Measure what you learn",paragraphs:[`After the decision or release, review the records rather than guessing from a single number. Compare the plan with what happened, note questions that remain, and make one or two practical changes for the next project. Reports can arrive on different schedules and may reflect different rights, territories, usage definitions and contractual arrangements, so avoid treating a short-term figure as a universal benchmark.`,`For additional context, use the primary references linked below and the specific terms that govern your project. General education cannot replace individual legal, tax or financial advice.`]}
 ];
 if(index===7) base[0].paragraphs=["Spotify for Artists lets teams pitch eligible unreleased songs to Spotify's editorial playlist editors. Delivery must happen first so the track appears in the Upcoming section. Spotify says to deliver at least seven days before release; that timing also matters for follower Release Radar eligibility. Pitching is consideration, not a placement promise.",...base[0].paragraphs.slice(1)];
 if(index===21) base[0].paragraphs=["India's Copyright Act recognises different categories of protected work, including musical works and sound recordings. A song's composition and lyrics are conceptually distinct from a particular recorded performance or master. The people involved and their agreements determine who owns or administers relevant rights; do not assume the vocalist or beat maker automatically controls every layer.",...base[0].paragraphs.slice(1)];
 if(index===20) base[0].paragraphs=["YouTube describes Content ID as a system that matches uploads against reference content supplied by approved copyright owners. Eligibility depends on demonstrating exclusive rights in the material submitted. A non-exclusive beat licence, a compilation or a recording containing material you cannot exclusively control may make a poor reference asset. Review YouTube's current eligibility rules before enrolling a track.",...base[0].paragraphs.slice(1)];
 if(index===1) base[0].paragraphs=["Music distribution is the delivery and administration layer that helps get a sound recording and its release information to digital services. A distributor can transmit audio and metadata, communicate delivery status and provide reports under its own agreement. Distribution does not itself create ownership, clear samples, guarantee acceptance, or make every platform report earnings in the same way.",...base[0].paragraphs.slice(1)];
 if(index===29) base[0].paragraphs=["Streaming royalty is not a universal fixed amount per play. Money is reported and allocated through platform, rights and contract arrangements that can vary by service, territory, subscription or advertising mix, rights ownership, distributor terms and collection route. A master owner and songwriters may be paid through different channels. Use actual statements and agreements to understand your own income.",...base[0].paragraphs.slice(1)];
 const practical: Record<number, BlogSection> = {
  0:{heading:"India to Spotify: a release-day walkthrough",paragraphs:["Choose a distributor and review its current terms, fees and delivery requirements. Prepare a lossless final master, square cover art that meets the distributor's technical rules, accurate track and contributor metadata, and written permission for every sample, beat or third-party element. Submit well before the date you want: review and store processing are separate steps, and neither has a universal guaranteed turnaround. Once delivery appears in Spotify for Artists, claim or access the correct artist profile using the artist link or URI supplied by your distributor.","Check the live listing after release for the right artist page, title, version and artwork. Save the release identifier, recording identifier where supplied, distributor confirmation and a copy of the final delivery package. Spotify's artist tools are free to access; delivery of music to Spotify is handled through a distributor. HYMN's distribution route and current first-release terms are described on the relevant service pages."],bullets:["Clear samples and confirm beat licence scope before upload.","Send the unreleased song to Spotify at least seven days before release if you want to pitch it through Spotify for Artists.","Review the live store page rather than assuming all services display metadata identically.","Keep project files and rights evidence available if a correction is needed."]},
  1:{heading:"What a distributor doesâ€”and leaves to you",paragraphs:["A distributor packages and sends a recording plus release data to digital services under a delivery agreement. Depending on the provider, it may provide identifiers, route updates, collect service reports, administer payments or offer optional tools. Those functions do not make the distributor the songwriter, master owner or rights-clearance lawyer. You remain responsible for having authority to deliver the recording and for the accuracy of the credits and release information.","Compare a distributor by reading the agreement and workflow rather than relying on the word free or a platform logo. Check what costs recur, how takedowns and corrections work, who handles customer questions, how reports are presented and whether a release can remain available if you stop paying. Spotify itself explains that music reaches it through distributors and that fees or commissions depend on the chosen provider. HYMN's published policy states the distribution partner share separately and says HYMN charges no additional royalty-percentage commission; release fees and optional services are separate."]},
  2:{heading:"Compare the total arrangement, not the headline price",paragraphs:["A free plan can be suitable when its conditions fit your release and the service remains useful over time. A paid plan may include capabilities or support that matter to your workflow, but a higher price does not automatically mean better delivery or better audience results. Put the full term beside the features you will actually use: annual renewal, per-release charges, revenue share, included stores, correction support, takedown handling, catalogue retention and reporting access.","For HYMN, the first-release promotion is conditional: eligibility checks include an active offer, a qualifying first submitted release and no active subscription; it applies to one new single in the one-time plan. The configured discount is capped at â‚¹99, so â€œfreeâ€ is not a universal claim that every release costs nothing. Confirm current availability and the exact checkout total in the release flow before relying on the offer. Compare that one-time offer with the current subscription or release pricing that applies to your own account."]},
  3:{heading:"Final delivery checklist by asset",paragraphs:["Audio: audition the exact final master from beginning to end, check the start and ending, remove accidental silence or clipped tails, and verify that the exported file meets the current distributor specification. If you have multiple tracks, confirm order and each track's version. Artwork: use original or cleared imagery, check dimensions and legibility at thumbnail size, and remove unintended logos, URLs or promotional copy if the destination rules prohibit them.","Metadata: compare title spelling, primary and featured artist roles, contributors, explicit status, language, genre, release date and label against the approved source sheet. Rights: retain beat licences, sample permissions, collaborator agreements and artwork releases. Identifiers: carry forward an existing code only when it truly refers to the same release or unchanged recording. Promotion: prepare a short description, approved links and a realistic timeline. Ask another person to review the package against the store and distributor's current specifications before submission."]},
  4:{heading:"Why timelines vary",paragraphs:["There are usually several clocks: your distributor's initial review, correction time if something is incomplete, delivery transmission, and each store's processing and display. A release can be accepted for delivery while not yet appearing publicly. Store schedules, territory availability, weekends, rights questions, metadata corrections and asset checks can all affect when a listing becomes visible. A distributor's estimate should be treated as guidance unless its current terms explicitly promise a service level.","Work backward from the date that matters. Allow room for review and resubmission, and do not schedule a campaign around a listing that has not been verified. Spotify says unreleased music appears in Spotify for Artists after a label or distributor delivers it; that is a separate checkpoint from your initial upload. If a date is critical, ask the distributor before announcing it, keep correspondence and submission IDs, and prepare a contingency that does not depend on an unconfirmed store page."]},
  5:{heading:"When to use each identifier",paragraphs:["An ISRC identifies a particular sound recording; a UPC or equivalent product code identifies a release product such as a single, EP or album in distribution workflows. One release can contain several recordings and therefore several ISRCs, while its product-level identifier is different. A remaster, edit, clean version or newly recorded performance may require a separate recording identifier depending on whether it is materially the same recording and on the distributor's rules.","Do not invent, reuse or copy a code from another artist's release. If the same unchanged recording is moving distributors, ask both providers how to preserve its existing ISRC and play-history mapping. For a new product, follow the delivery provider's assignment process and keep a catalogue spreadsheet that maps titles, versions, ISRCs, UPCs, release dates and ownership. The code is an identifier, not evidence of copyright ownership, permission or a royalty split."]},
  6:{heading:"Three playlist pathways",paragraphs:["Editorial playlists are selected by Spotify's editorial teams; artists can submit eligible unreleased tracks through Spotify for Artists, but cannot buy a guaranteed position. Personalized or algorithmic surfaces use platform systems and listener signals to recommend music to individuals; no artist can force a recommendation. User-curated playlists are created by listeners or other third parties, whose taste and audience quality vary. A playlist's name alone does not prove genuine listening or fit.","Treat each pathway differently: give editors concise, accurate context; make it easy for existing fans to save and return to a song; and research independent playlist owners before submitting. Avoid any offer that guarantees streams or a placement for payment. Spotify warns that third-party services promising streams violate its rules and can lead to consequences for a release. Focus on relevance and real listeners, and track saves, engaged listeners and meaningful audience actions rather than playlist count alone."]},
  7:{heading:"A strong, accurate pitch",paragraphs:["After your distributor delivers the release, open Spotify for Artists and check Upcoming. Select an eligible unreleased song and complete the pitch form with precise genre, mood, instrumentation, language, culture or scene context, and a short explanation of the track's story and campaign. Describe what is genuinely distinctive; avoid inflated claims, irrelevant name-dropping or copy-and-paste pitches. Give editors enough detail to understand who the music is for and why.","Spotify currently advises delivering at least seven days before release for editorial pitching and follower Release Radar eligibility. Earlier submission gives you more time to fix delivery or metadata issues, but does not guarantee that an editor hears or selects the song. Pitch one song at a time as the tool permits, verify the correct artist profile and release, and do not pay an intermediary who promises placement. Keep a copy of your pitch and spend the rest of your campaign reaching listeners directly."]},
  8:{heading:"Evaluate playlists before you submit",paragraphs:["Start with audience fit: listen to recent additions, compare the playlist's sound and mood with your track, and check whether the curator explains how submissions are handled. Look for a coherent sequence and signs that the playlist is maintained. A large follower number is not proof that followers listen. Ask what a submission fee buys. A review or feedback service is different from purchasing inclusion, streams or a guaranteed duration.","Use your own channels to give real listeners a reason to hear the release: a short performance clip, production breakdown, collaboration story, local scene connection or direct note to people who already engage. Never use bots, fake playlists, guaranteed-stream campaigns or paid placement claims. Such activity can distort your data and expose the release to platform enforcement. Keep a small log of curator, date, terms, response and actual result so future outreach is based on evidence instead of hype."]},
  9:{heading:"Allocate a small budget deliberately",paragraphs:["Write down the audience you want to reach and one action you hope they take before spending. Your first costs may be production essentials, artwork, a clean landing page, transport for a performance clip or a modest test of a relevant advertisement. Choose one channel where you can identify the audience and observe what happened. Make a simple plan for creative, duration, cap and success measure before launching.","Do not divide a tiny budget across many unrelated services just because each promises exposure. Paid reach is not the same as listening, saves or lasting fans. Avoid vendors selling guaranteed streams or playlist positions. Use available platform analytics and campaign link tracking to learn which message led people to the music, then stop or adjust weak tests. Keep some time for no-cost work: personal outreach, consistent short-form content, collaborations and follow-up with listeners who have opted into hearing from you."]},
  10:{heading:"A release timeline you can actually follow",paragraphs:["Before release, settle rights and collaborator approvals, finish the master, prepare artwork and metadata, submit with enough lead time, and verify that the track appears in the correct artist profile. Build a lightweight campaign around assets you can deliver consistently. If using Spotify editorial pitching, submit eligible unreleased music through Spotify for Artists at least seven days ahead. Share a pre-save or announcement only when the destination link and date are confirmed.","On release day, check store availability, artist mapping, audio and credits; correct a real error through the distributor rather than uploading a duplicate. Share the listening link with a clear invitation and credit collaborators. After launch, thank people, post a second angle on the song, review audience feedback and platform reporting, and note what you would repeat. Avoid interpreting a single day's play count as a career forecast: release discovery and reporting happen over different periods."]},
  11:{heading:"Build a beat catalogue buyers can trust",paragraphs:["Prepare consistent previews and label each instrumental with a distinct title, tempo and key only when you have checked those details. Make the purchase page explain exactly what the buyer receives: file formats, stems if included, licence type, permitted distribution and monetization, credit requirement, usage caps, term, territory and any exclusions. State whether the beat is non-exclusive or exclusive and how an exclusive purchase affects future listings and prior licences.","In India, accept payment through a method that gives both parties a clear receipt and retain the licence version attached to the transaction. Keep proof of ownership or authorization for loops, samples and collaborators. Establish a delivery and support process before listing, and test files on a separate device. A marketplace can handle discovery and records, but cannot grant rights you do not control. HYMN's Beat Store terms specify that the written licence and selected tier govern permitted use; check those terms and each listing before buying or selling."]},
  12:{heading:"Understand what changes with exclusivity",paragraphs:["A non-exclusive beat licence usually lets the producer license the same instrumental to multiple buyers under defined limits. An exclusive transaction may stop future sales, but its exact effect depends on the written agreement: it does not automatically erase earlier valid licences or transfer every copyright interest. The term â€œexclusiveâ€ can refer to availability, rights scope or a contractual promise, so define it instead of relying on the label.","Compare the permitted uses, number of monetized recordings or views, audio-only versus audiovisual use, distribution cap, publishing share, credit, sublicensing, Content ID eligibility, territory, term, refund and takedown terms. Confirm who owns the composition and master after a vocal is added and whether the producer retains writer share. Save the actual signed licence and payment proof. If the use you needâ€”such as an advertisement, film, sample pack or exclusive fingerprintâ€”is not named, get written clarification before release."]},
  13:{heading:"Set a price from the licence and the work",paragraphs:["Begin with your delivery cost and the rights granted. A basic non-exclusive download with limited use is not the same product as a licence with stems, broad monetization, custom edits or exclusive availability. Factor in the time to produce, revise, organize and support a sale, along with any marketplace fee and tax obligations that apply to you. Compare similar offers as context, not as proof that their price is right for your catalogue.","Create a small, understandable ladder only when each tier has a real difference in deliverables or permitted use. Write the limits beside the price so buyers can compare without guessing. Track views, questions and purchases over a meaningful period; change one variable at a time and note the date. Do not set an artificially low price to imply rights that the licence does not grant. Revisit pricing when your catalogue, costs, demand or service changes, and honor the terms attached to earlier transactions."]},
  14:{heading:"Licence clauses to read line by line",paragraphs:["A practical beat licence should identify the licensor and licensee, the beat and version, the effective date, the grant of rights and whether it is exclusive. It should define allowed recording, distribution, public performance, monetization, sync and promotional use, plus any limits on copies, streams, videos, paid advertising or territories. It should name the files delivered and describe whether the buyer can edit or create derivatives.","It should also state price and payment, credit format, songwriter or publishing shares if agreed, term and renewal, restrictions on resale or Content ID, what happens if the producer receives a rights claim, and how amendments or termination work. There is no one universal licence template. Do not assume buying a file transfers copyright; make the grant explicit and get independent legal advice for a high-value or unusual deal. Retain the exact licence that applied at checkout, not only a later version of the listing."]},
  15:{heading:"A session mix and a release master",paragraphs:["Mixing works with the individual tracks in a session: vocals, drums, bass, instruments and effects. The mixer balances levels, tone, dynamics, space and movement so the parts serve the song together. Mastering works from the approved stereo mix (or a properly prepared format requested by the engineer), checking translation, tonal balance, loudness and delivery requirements across playback contexts. Mastering cannot reliably fix every performance, arrangement or clipping problem buried in a finished stereo file.","A useful workflow is to finish arrangement edits first, share references and creative priorities with the mixer, approve the mix, then send the approved mix plus destination requirements to mastering. Ask whether the mastering engineer expects headroom or a particular file format; do not apply a generic number as a rule. Compare versions at matched loudness, listen on headphones, speakers and a phone, and keep both the approved premaster and final deliverables. Mixing and mastering are related but distinct stages, and some engineers offer a combined service with separate checks."]},
  16:{heading:"Export stems that line up",paragraphs:["A stem handoff should make it possible to rebuild the session without guessing. Export every file from the same start point so all stems line up, use clear filenames such as songname_drums_124bpm.wav, and include the tempo and sample rate in a text note. Check that vocal doubles, ad-libs, effects returns and instrumental buses are either included or intentionally omitted. Tell the engineer whether the rough mix uses automation or processing that is important to the sound.","Do not normalize each stem independently if that changes the balance, and do not accidentally print a limiter that is not part of the creative direction. Include a reference mix and a short note describing what you like and what needs attention. If the session uses plugins that cannot be shared, print the intended effects as separate wet stems and provide dry versions when requested. Re-import the exported files into a blank session to confirm timing, tails and completeness before upload; keep the original project backed up."]},
  17:{heading:"Record a clean vocal at home",paragraphs:["Room sound often matters more than buying another microphone. Choose the quietest space, reduce obvious reflections with soft furnishings placed safely, and keep the performer a consistent distance from the mic. Use a pop filter, turn off fans and notifications, and record a short test while listening for room echo, traffic, computer noise and harsh plosives. Set input gain so loud phrases do not clip; leave level adjustments for the mix rather than recording too hot.","Warm up, mark lyric changes and record complete takes before punching small fixes. Keep breaths and ad-libs intentional, name takes clearly, and avoid destructive editing on the only copy. Save a dry vocal and a rough reference so the engineer can hear the performance context. If you use pitch correction, saturation or reverb while tracking, tell the mixer and provide an unprocessed option where possible. Back up the session and exports to a second location before clearing storage."]},
  18:{heading:"Assess fit before hiring",paragraphs:["Listen to work in a similar genre and arrangement, not just a polished highlight reel. Ask whether the examples represent the engineer's own work, what the project included, and whether you can hear a full before-and-after or comparable release. Discuss your intended references, timeline, number of tracks, deliverables, revision definition, communication channel and what happens if the direction misses the brief. A clear process is as important as impressive equipment.","Confirm the total price and payment milestones in writing. Clarify whether the quote covers editing, tuning, mix, master, instrumental, clean version, stems and alternate formats. Share files through the agreed secure workflow, not a public link containing private demos. Before booking, verify that the engineer is available during the period you need. HYMN Studio lists engineers and project terms through its service pages; compare the actual profile, turnaround and included revisions rather than assuming every listing has identical terms."]},
  19:{heading:"Map the song and the recording separately",paragraphs:["A composition is the underlying musical work: commonly the music and lyrics. A master is a particular recorded performance fixed as a sound recording. One song can have many masters, such as a studio version, live recording, remix or cover. Different people or companies may own or administer these layers, and one person's contribution can involve more than one role. The legal result depends on applicable law, facts and agreements.","Make two columns in your split sheet: composition contributors and recording contributors or master owner. Then record the rights granted to a label, distributor, producer, publisher or licensee, including territory, term and uses. A distribution agreement for a master does not automatically resolve publishing administration, and a songwriter registration does not itself prove control of a recording. For an Indian project, consult the Copyright Act and a qualified lawyer for a disputed or high-value rights question; this article is general education, not individual legal advice."]},
  20:{heading:"Agree the split before release",paragraphs:["Separate songwriting shares from the producer's fee, master ownership and any royalty participation. A producer may contribute to composition, receive a production fee, share in the master, or have a negotiated combination; there is no universal automatic percentage. Discuss the contribution while memories are fresh and before distribution metadata or registrations are submitted. Do not use a split sheet to silently replace a signed production agreement.","Write each contributor's legal or professional name, contact, role, composition share, master arrangement if relevant, payment terms, collection or administrator details and approval date. Make sure the shares in each category total the agreed whole. Explain how samples, interpolations, remixes and later edits affect the deal. Every collaborator should receive the final signed record. If the parties disagree, pause release and get advice rather than entering a convenient but inaccurate split that may later block licensing or income."]},
  21:{heading:"Understand matches, claims and eligibility",paragraphs:["A Content ID match is not the same thing as a court decision or proof that every detected use is infringing. A rights holder or its authorized partner may use a match to apply a policy such as monetizing, tracking or restricting a video. Disputes follow YouTube's procedures and can have consequences, so only challenge a claim when you have a good-faith basis and supporting rights evidence.","Before enrollment, identify every element in the recording: composition, beat, samples, loops, vocals and any licensed library material. YouTube requires exclusive rights to the material supplied as reference; a non-exclusive lease or shared loop may disqualify the reference even if your new vocal is original. Keep the licence and source files. Ask the administrator which territories and assets are covered, how claims are released, and how revenue or fees are reported. YouTube's own eligibility guidance is the controlling starting point; eligibility is not guaranteed by a distributor add-on."]},
  22:{heading:"Keep rights records from the first session",paragraphs:["Copyright questions often begin with a practical inventory: who wrote the music and lyrics, who performed, who financed or produced the recording, what samples or beats were used, and what agreements cover each contribution? Preserve dated session files, split sheets, invoices, licences, consent and release forms. A copyright registration is a separate administrative step; registration and ownership are not concepts to treat as interchangeable without checking the relevant statute and facts.","The Indian Copyright Act covers multiple work categories, including musical works and sound recordings, and defines rights and exceptions in statutory terms. Do not assume that uploading a song transfers copyright or that buying a beat grants every possible use. Clear samples and obtain permission for cover or adaptation uses as required. For a dispute, commercial sync, assignment or complex collaboration, seek a qualified Indian copyright lawyer. This overview is educational and does not interpret your individual contract or provide legal advice."]},
  23:{heading:"A metadata handoff that reduces errors",paragraphs:["Create one approved spreadsheet before delivery. Keep release title, track titles, version, primary artist, featured artists, contributor names and roles, explicit status, language, genre, release date, label, territories, identifiers and rights contact in separate fields. Use consistent spelling across the cover, lyric sheet, registrations, distributor form and artist profile. Check that a feature is credited in the correct role and that artist names map to the intended profiles.","Identifiers must follow the recording and product they identify; do not reuse an ISRC for a new recording or copy a UPC from another release. If the same recording is re-delivered, verify the prior code with the distributor. Metadata errors can cause a wrong artist mapping, delayed review or mismatched reporting; they do not automatically erase ownership, but they make correction and reconciliation harder. Store the submitted snapshot, confirmation and later changes together so you can explain what was sent and when."]},
  24:{heading:"Pick a format around the listener's experience",paragraphs:["A single lets you focus attention and learn from one finished release. An EP can present a small connected body of work without requiring a full-length album campaign. An album gives more room for range or narrative, but it also asks listeners to spend more time and may require more production, rights coordination and promotion resources. These are planning trade-offs, not algorithmic rules; platforms do not guarantee better reach for one format.","Ask whether each track is ready, whether the songs work together, how often you can communicate with listeners, and whether a shorter sequence will help you finish and promote the work. Consider collaborators' schedules and the costs of visuals, mixing, mastering and clearances. A staged single strategy can create several campaign moments, but only if each release has a reason and does not exhaust your audience. Choose the smallest coherent project that expresses the work you want people to hear now."]},
  25:{heading:"Four weeks, with a clear job for each",paragraphs:["Days 30â€“22: confirm rights, final mix, artwork, credits and delivery; choose a date only after checking the distributor's lead-time guidance. Days 21â€“15: prepare the artist profile, short-form clips, story and direct outreach list; submit eligible Spotify pitches through Spotify for Artists once the release appears in Upcoming. Days 14â€“8: share a useful preview, invite collaborators to coordinate and test links. Days 7â€“1: confirm the listing, schedule posts and send personal reminders without spamming.","Release week: verify the live track and artist mapping, publish the strongest creative asset, thank contributors and make the listening link easy to find. The next three weeks: share a different angle, answer genuine listener responses, review available analytics and document what performed. Adapt the calendar to your capacity and audience; the plan does not promise a placement or stream count. If delivery slips, communicate the change clearly rather than promoting an unavailable link."]},
  26:{heading:"Treat the career as a small creative business",paragraphs:["Build a sustainable practice around repeatable actions: finish songs, maintain relationships with listeners, keep rights and payment records, and review costs before committing to a campaign. Set a creative target and an operational target for each quarter. For example, finishing demos is within your control; a particular stream count or income level is not. Separate personal and project expenses where practical, keep receipts and plan for irregular income rather than assuming one release will pay for the next.","Use a simple catalogue of works, collaborators, masters, agreements, release links and income statements. Learn which activities lead to meaningful connection, but leave room for experimentation and rest. Diversifying income may include performance, commissions, production, licensing or teaching, depending on your skills and rights; none is guaranteed. Ask an accountant about tax obligations and a lawyer about contracts when needed. A sustainable career is built from a portfolio of work and relationships over time, not a single platform metric."]},
  27:{heading:"Rapper-specific checks before delivery",paragraphs:["Confirm that the beat licence permits the planned commercial release, distribution territories, video use and monetization. Clear any sample in the instrumental and make sure the producer's credit and agreed composition or master participation are documented. Check featured verses, producer tags, spoken samples, borrowed lyrics and artwork permissions. If you intend to release clean and explicit versions, name and deliver each version correctly and avoid treating an edited master as identical to the original recording for identifier purposes without checking guidance.","Prepare artist spellings, feature order, language, explicit flag and cover text consistently. For a Hindi, Punjabi, Tamil or Hinglish release, have a fluent collaborator review transliteration and title presentation. Set a date with enough delivery lead time and confirm the correct artist profile after the track appears. Promotion can highlight the writing, beat choice, performance or local scene; don't buy guaranteed streams. Keep the split sheet and licence alongside the final master and delivery receipt."]},
  28:{heading:"The studio can connect creative work to delivery",paragraphs:["A studio may support more than microphone time: pre-production planning, arrangement feedback, recording, comping, editing, session organization and a clean handoff to mixing or mastering. Agree what is included before booking. A session engineer can help capture a good performance, but recording does not automatically include a mix, master, beat licence, songwriting share or distribution service. Put those responsibilities and fees in the project brief.","Ask for a copy of the session or stems, file format, naming convention and delivery date if you will continue with another engineer. Discuss confidentiality, backups, revisions and whether the studio can use excerpts in a portfolio. Keep rights in the recording and composition clear among artist, producer, engineer and studio. Before the final session, prepare lyrics, references and a track plan to use paid time well. HYMN Studio profiles show the services and terms available for individual engineers; check the listing before booking." ]},
  29:{heading:"Follow the reporting path without assuming a rate",paragraphs:["Streaming revenue begins in service-level reporting and moves through contractual and rights-administration arrangements. A recording's master royalties may flow to a label or master owner through a distributor, while composition income may be collected through publishers, societies or other channels according to territory and usage. Collaborator splits, distribution shares, taxes, adjustments, minimum thresholds and payout verification can change what reaches an individual. There is no stable universal per-stream payout figure that applies to every listener or artist.","Read statements by period, territory, service, asset and revenue type. Check unmatched recordings, missing registrations and collaborator splits, then compare the report with the governing agreement. For HYMN distribution, the published policy says the distribution partner retains 30% of Net Royalty Revenue and HYMN adds no royalty-percentage commission; the eligible balance remains subject to reports, collaborator splits, adjustments and payout conditions. This is not 70% of gross store revenue or a guarantee of immediate cash. Do not use a stream calculator as a substitute for your actual statement."]}
 };
 if(practical[index]) base.push(practical[index]);
 return base;
}

const artworkForCategory:Record<string,{image:string;imageAlt:string}>={"Music Distribution":{image:"/assets/blog/music-distribution.svg",imageAlt:"Audio waveform and release preparation notes"},"Playlist Curation and Promotion":{image:"/assets/blog/playlist-promotion.svg",imageAlt:"Headphones and a notebook for planning music promotion"},"Beat Store and Licensing":{image:"/assets/blog/beat-licensing.svg",imageAlt:"Producer's workstation with a beat session open"},"Mixing and Mastering":{image:"/assets/blog/mixing-mastering.svg",imageAlt:"Mixing console in a recording studio"},"Music Rights and Royalties":{image:"/assets/blog/music-rights.svg",imageAlt:"Music agreement and recording notes on a desk"},"Artist Development":{image:"/assets/blog/artist-development.svg",imageAlt:"Independent artist preparing a release plan"},"Recording Studios":{image:"/assets/blog/recording-studio.svg",imageAlt:"Microphone in a recording booth"}};
export const BLOG_ARTICLES: BlogArticle[] = specs.map((s,i)=>({slug:s[0],title:s[1],category:s[2],excerpt:s[3],tags:s[4].split(" "),publishedAt:"2026-10-26",updatedAt:"2026-10-26",featured:i===0,...artworkForCategory[s[2]],service:s[5]?{label:"Explore HYMN's relevant service",href:s[5]}:undefined,sections:contentFor(i,s[1]),sources:[...(i===0||i===4||i===23||i===27?[spotifyStart]:[]),...(i===6||i===7?[spotify,spotifyArtificial]:[]),...(i===8||i===9?[spotifyArtificial]:[]),...(i===19||i===20?[copyright,iprs]:[]),...(i===21?[youtube]:[]),...(i===22?[copyright,iprs]:[]),...(i===24||i===25?[spotify]:[]),...(i===29?[iprs]:[]) ]}));

export function readingMinutes(article:BlogArticle){const words=[article.title,article.excerpt,...article.sections.flatMap(s=>[s.heading,...s.paragraphs,...(s.bullets||[])])].join(" ").split(/\s+/).length;return Math.max(4,Math.ceil(words/220));}
export function getBlogArticle(slug:string){return BLOG_ARTICLES.find(a=>a.slug===slug);}
export function getRelatedArticles(article:BlogArticle){return BLOG_ARTICLES.filter(a=>a.slug!==article.slug&&(a.category===article.category||a.service?.href===article.service?.href)).slice(0,3);}
export function slugifyCategory(category:string){return category.toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/(^-|-$)/g,"");}
